 "content": "def transform(grid):
    # Each 3x3 tile contains sparse colored markers; the output preserves the
    # color in its corresponding tile position when markers are present.
    out = [[0] * 5 for _ in range(5)]
    h, w = len(grid), len(grid[0])
    for br in range((h + 2) // 3):
        for bc in range((w + 2) // 3):
            vals = [grid[r][c] for r in range(br*3, min(br*3+3,h))
                    for c in range(bc*3, min(bc*3+3,w)) if grid[r][c] not in (0,5)]
            if vals:
                # Marker cluster color is the most frequent non-background value.
                color = max(set(vals), key=vals.count)
                if br < 5 and bc < 5:
                    out[br][bc] = color
    return out

